SELECT code, level, title, COALESCE(summary,'') AS summary, COALESCE(explain,'') AS explain, COALESCE(connection,'') AS connection, COALESCE(examples,'') AS examples, examples_edited, COALESCE(orig_title,'') AS orig_title, seq, COALESCE(item_codes,'') AS item_codes, COALESCE(point_codes,'') AS point_codes FROM textbook_import_draft WHERE task_id = CAST(:task_id AS INTEGER) AND status = '通过' ORDER BY seq ASC, id ASC
